SourceCode.Declaration:
[METTMSEngineDocumentTypeAttribute(METTMSSourceDocumentType::SalesOrderDocument)]
public class METTMSEngineHeaderSalesOrderContract extends METTMSEngineHeaderContract
{
    METSalesTable metSalesTable;
    METSalesOrderTypes salesOrderTypes;

}

Method.Source:
/// <summary>
/// Initialize the data contract variables
/// </summary>
public void init()
{
    metSalesTable = METSalesTable::findByRefRecId(sourceRecord.RecId);
    headerExtMap = metSalesTable;
}

/// <summary>
/// Gets the header records extension buffer
/// </summary>
/// <returns>Extension table record buffer</returns>
public Common getExtensionTable()
{
    Common ret;

    ret = metSalesTable;

    return ret;
}

/// <summary>
/// Gets the order route id
/// </summary>
/// <returns>Route id</returns>
public METRoute getRoute()
{
    return sourceRecord.Route;
}

/// <summary>
/// Construct and return shipment id
/// </summary>
/// <returns>Shipment Id</returns>
public METTMSShipmentID getShipmentID()
{
    if(!shipmentId)
    {
        str shippingDateStr = date2Str
        (this.getShipDate(),
            321,
            DateDay::Digits2,
            DateSeparator::None,
            DateMonth::Digits2,
            DateSeparator::None,
            DateYear::Digits4);

        shipmentId = strFmt("@MET:ShipmentStrFmt",
        sourceRecord.InventLocationFrom,
        sourceRecord.CustomerAccount,
        sourceRecord.Route,
        shippingDateStr);
    }

    return super();
}

/// <summary>
/// Gets receipt date of the order
/// </summary>
/// <returns>Receipt date</returns>
public TransDate getReceiptDate()
{
    TransDate ret;

    ret = super();

    if(!ret)
    {
        ret = sourceRecord.RequestedReceiptDate;
    }

    return ret;
}

/// <summary>
/// Get the route stop number
/// </summary>
/// <returns>Route stop number</returns>
public METRouteStopNum getRouteStop()
{
    METRouteStopNum ret = sourceRecord.RouteStop;

    return ret;
}

/// <summary>
/// GEts the destination type of the order
/// </summary>
/// <returns>Destination type, either customer or warehouse</returns>
public METDestinationType getDestinationType()
{
    return METDestinationType::Customer;
}

/// <summary>
/// Validate if Sales order excluded from TMS engine
/// </summary>
/// <returns>
/// a boolean value<c>boolean</c> query.
/// </returns>
public boolean isOrderExcluded()
{
    boolean ret = false;

    if(!salesOrderTypes)
    {
        salesOrderTypes = METSalesOrderTypes::find(sourceRecord.OrderType);
    }

    if (salesOrderTypes.RecId)
    {
        ret = salesOrderTypes.ExcludeFromTMSEngine;
    }

    return ret;
}

/// <summary>
/// Gets the shipment date of the order
/// </summary>
/// <returns>Shipment date</returns>
public TransDate getShipDate()
{
    TransDate ret;

    ret = super();

    if(!ret)
    {
        ret = sourceRecord.RequestedShipDate;
    }

    return ret;
}

/// <summary>
/// Gets the customer account of the order
/// </summary>
/// <returns>Customer account number</returns>
public CustAccount getCustomerAccount()
{
    return sourceRecord.CustomerAccount;
}

/// <summary>
/// Get success or failure message
/// </summary>
/// <param name = "_shipmentCreated">Is shipment created</param>
/// <returns>Success or failure message</returns>
public SysInfoLogStr showInfo(boolean _shipmentCreated)
{
    SysInfoLogStr msg;

    if (_shipmentCreated)
    {
        msg = strFmt("@MET:TMSEngineSuccessMessage", this.parmSourceRecord().OrderId);
    }
    else
    {
        msg = strFmt("@MET:TMSEngineCompletedMessage", this.parmSourceRecord().OrderId);
    }

    return msg;
}

/// <summary>
/// Is this an internal cross dock order
/// </summary>
/// <returns>true, if the order is internal cross dock otherwise false.</returns>
public NoYes isInternalCrossDockOrder()
{
    NoYes ret;

    ret = false;

    return ret;
}

/// <summary>
/// Gets the carrier code of the order
/// </summary>
/// <returns>Carrier code</returns>
public TMSCarrierCode getCarrierCode()
{
    TMSCarrierCode ret;

    if(!carrierCode)
    {
        carrierCode = TMSSalesTable::find(sourceRecord.OrderId).CarrierCode;
    }

    ret = super();

    return ret;
}
